#![allow(dead_code, non_snake_case, unused_variables, clippy::needless_range_loop)]


#[derive(Clone)]
pub struct GlobalState {
    pub _state: u64,
}
impl Default for GlobalState {
    fn default() -> Self { Self { _state: 0 } }
}
impl GlobalState {
    pub fn footprint(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(&self._state.to_ne_bytes());
        out
    }
}



pub fn prng_seed(st: &mut GlobalState, s: u64) {
    st._state = s;
}
pub fn prng_next(st: &mut GlobalState) -> u64 {
    st._state = st._state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    st._state >> 33
}

